    parser.buffer_text = 1
    out = ExternalOutputter(parser)
    parser.ExternalEntityRefHandler = out.ExternalEntityRefHandler
    parser.Parse(data, True)
    assert out.parser_result == 1, ('assertEqual', out.parser_result, 1)
